// Definition of an interval with a strict ordering min < max
#[derive(Debug, Clone, PartialEq)]
pub struct Interval {
    pub min: f64,
    pub max: f64,
}

impl Interval {
    /// Constructs a new Interval.
    /// Panics if `min >= max`.
    pub fn new(min: f64, max: f64) -> Self {
        assert!(
            min < max,
            "Invalid interval: min ({}) must be < max ({})",
            min,
            max
        );
        Interval { min, max }
    }
}

// Descriptor for a Chebyshev polynomial
#[derive(Debug, Clone, PartialEq)]
pub struct ChebyshevPoly {
    pub coefficients: Vec<i32>,
    pub domain: Interval,
    pub window: Interval,
}

/// Constructs a Chebyshev polynomial descriptor from an input sequence of
/// 8-bit signed coefficients (in increasing degree order). The coefficients
/// are promoted to 32-bit signed integers. The domain and window intervals
/// are both set to [-1, 1].
///
/// # Panics
///
/// Panics if the input `coef` vector is empty or if interval construction fails.
pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // Ensure the input is non-empty
    assert!(
        !coef.is_empty(),
        "Coefficient list must be non-empty"
    );

    // Promote coefficients to i32, preserving order
    let coefficients: Vec<i32> = coef.into_iter().map(i32::from).collect();

    // Default domain and window intervals [-1, 1]
    let domain = Interval::new(-1.0, 1.0);
    let window = Interval::new(-1.0, 1.0);

    ChebyshevPoly {
        coefficients,
        domain,
        window,
    }
}

